package com.otgflasher.pro;import android.app.Activity;import android.os.Bundle;import android.widget.*;import java.io.*;public class OdinActivity extends Activity{TextView txtDetail,log;ProgressBar bar;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_odin);txtDetail=findViewById(R.id.txt_detail);log=findViewById(R.id.log_view);bar=findViewById(R.id.progress_bar);findViewById(R.id.btn_back).setOnClickListener(v->finish());findViewById(R.id.btn_flash_ap_0).setOnClickListener(v->run("heimdall flash --AP /sdcard/Download/AP.tar.md5"));
findViewById(R.id.btn_flash_bl_1).setOnClickListener(v->run("heimdall flash --BL /sdcard/Download/BL.tar.md5"));
findViewById(R.id.btn_flash_full_ap_bl_cp_csc_2).setOnClickListener(v->run("heimdall flash --AP /sdcard/Download/AP.tar.md5 --BL /sdcard/Download/BL.tar.md5 --CP /sdcard/Download/CP.tar.md5 --CSC /sdcard/Download/CSC.tar.md5"));
findViewById(R.id.btn_read_pit_3).setOnClickListener(v->run("heimdall print-pit"));
findViewById(R.id.btn_dump_pit_4).setOnClickListener(v->run("heimdall download-pit --output /sdcard/Download/pit.pit"));
findViewById(R.id.btn_bypass_kg_5).setOnClickListener(v->run("adb shell pm disable-user --user 0 com.samsung.android.kgclient"));
findViewById(R.id.btn_bypass_mdm_6).setOnClickListener(v->run("adb shell pm disable-user --user 0 com.samsung.android.mdm"));
findViewById(R.id.btn_bypass_frp_7).setOnClickListener(v->run("adb shell content insert --uri content://settings/secure --bind name:s:user_setup_complete --bind value:s:1"));
}void run(String c){bar.setProgress(5);log.append("\n> "+c+"\n");new Thread(()->{try{Process p=Runtime.getRuntime().exec(new String[]{"sh","-c",c+" 2>&1"});BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String l;int pr=5;while((l=r.readLine())!=null){pr+=2;if(pr>95)pr=95;String ll=l;int pp=pr;runOnUiThread(()->{bar.setProgress(pp);txtDetail.setText(pp+"% "+ll);log.append(ll+"\n");});}p.waitFor();runOnUiThread(()->bar.setProgress(100));}catch(Exception e){runOnUiThread(()->log.append("ERR "+e.getMessage()+"\n"));}}).start();}}